// --- Cannibalization detector (met normalisatie) ---
// Doel:
// 1) keyword_clean maken (zodat "werkenbij-website" == "werkenbij website")
// 2) url_clean maken (zodat #/ ? rommel weg is)
// 3) Cannibalization markeren: zelfde keyword_clean => meerdere unieke urls

function normalizeKeyword(keyword) {
  return (keyword || "")
    .toLowerCase()
    .trim()
    .replace(/[_-]+/g, " ")     // - en _ naar spatie
    .replace(/\s+/g, " ");     // dubbele spaties weg
}

function cleanUrl(url) {
  return (url || "")
    .trim()
    .split("#")[0]             // fragment weg
    .split("?")[0];            // querystring weg
}

const keywordMap = {}; // { keyword_clean: { urlsSet:Set, items:[] } }

for (const item of items) {
  // Zorg dat deze velden altijd bestaan
  item.json.keyword_clean = item.json.keyword_clean || normalizeKeyword(item.json.keyword);
  item.json.url_clean = item.json.url_clean || cleanUrl(item.json.url);

  const key = item.json.keyword_clean;
  if (!keywordMap[key]) {
    keywordMap[key] = { urlsSet: new Set(), items: [] };
  }

  keywordMap[key].urlsSet.add(item.json.url_clean);
  keywordMap[key].items.push(item);
}

// Zet flags terug op alle items
const result = [];

for (const [key, group] of Object.entries(keywordMap)) {
  const uniqueUrls = Array.from(group.urlsSet);
  const isCannibal = uniqueUrls.length > 1;

  for (const item of group.items) {
    item.json.cannibalization = isCannibal;
    item.json.cannibalization_group_size = uniqueUrls.length;
    item.json.cannibalization_urls = uniqueUrls; // handig voor manual review
    result.push(item);
  }
}

return result;

// Doel: 1 item per url_clean
// - kies primary keyword (hoogste volume, dan beste positie)
// - verzamel rest als secondary_keywords

const map = {};

for (const item of items) {
  const url = item.json.url_clean || item.json.url;
  if (!map[url]) map[url] = [];
  map[url].push(item);
}

const out = [];

for (const [url, group] of Object.entries(map)) {
  // Sort: hoogste volume eerst, bij gelijk volume: beste positie (laagste getal)
  group.sort((a, b) => {
    const volA = Number(a.json.volume ?? 0);
    const volB = Number(b.json.volume ?? 0);
    if (volB !== volA) return volB - volA;

    const posA = Number(a.json.position ?? 999);
    const posB = Number(b.json.position ?? 999);
    return posA - posB;
  });

  const best = group[0];

  best.json.primary_keyword = best.json.keyword_clean || best.json.keyword;
  best.json.secondary_keywords = group
    .slice(1)
    .map(x => x.json.keyword_clean || x.json.keyword);

  best.json.secondary_keywords = [...new Set(best.json.secondary_keywords)];

  best.json.keywords_all = [best.json.primary_keyword, ...best.json.secondary_keywords];

  // Handig om te weten dat dit samengevoegd is
  best.json.grouped_rows = group.length;

  out.push(best);
}

return out;

// Verrijkt elke ruwe rij voor de Data Table.
//
// secondary_keywords_text: de overige zoekwoorden waarop DEZELFDE URL rankt,
// hoogste volume eerst. Dit gebeurt bewust hier, voor de positie- en
// volumefilters verderop, zodat ook zoekwoorden waar de pagina al top-4 op
// staat in de lijst komen - juist die zijn in de rest van de flow onzichtbaar.

const cleanUrl = (url) => String(url || '')
  .trim()
  .split('#')[0]
  .split('?')[0];

const normalizeKeyword = (keyword) => String(keyword || '')
  .toLowerCase()
  .trim()
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ');

// Per URL alle zoekwoorden verzamelen, hoogste volume eerst, dan beste positie.
const byUrl = new Map();

for (const item of items) {
  const j = item.json;
  const url = cleanUrl(j.url);
  if (!byUrl.has(url)) byUrl.set(url, []);
  byUrl.get(url).push({
    keyword: normalizeKeyword(j.keyword),
    volume: Number(j.volume ?? 0),
    position: Number(j.position ?? 999),
  });
}

for (const list of byUrl.values()) {
  list.sort((a, b) => (b.volume - a.volume) || (a.position - b.position));
}

return items.map(item => {
  const j = item.json;
  const url = cleanUrl(j.url);
  const self = normalizeKeyword(j.keyword);

  // Alles op deze URL behalve het zoekwoord van de rij zelf, ontdubbeld.
  const seen = new Set([self]);
  const others = [];
  for (const k of (byUrl.get(url) || [])) {
    if (!k.keyword || seen.has(k.keyword)) continue;
    seen.add(k.keyword);
    others.push(k.keyword);
  }

  return {
    json: {
      ...j,
      intents_text: Array.isArray(j.intents) ? j.intents.join(',') : (j.intents ?? ''),
      serp_features_text: Array.isArray(j.serp_features) ? j.serp_features.join(',') : (j.serp_features ?? ''),
      // Bewust een eigen naam: 'Dedupe per URL' zet verderop zijn eigen
      // secondary_keywords en die mag hier niet mee botsen.
      secondary_keywords_page: others,
      secondary_keywords_text: others.join(', '),
      keywords_on_url: others.length + 1,
    }
  };
});

