const raw = $json.url_clean;

if (!raw || typeof raw !== 'string') {
  return { slug: null, keyword: null, primary_keyword: null, secondary_keywords: [] };
}

// verwijder protocol + domein: https://www.example.nl/pad -> pad
const slug = raw
  .replace(/^https?:\/\/[^\/]+\/?/i, '')
  .replace(/\/$/, '');                   // trailing slash

// primair zoekwoord: genormaliseerde variant, val terug op het ruwe keyword
const primary = $json.primary_keyword || $json.keyword_clean || $json.keyword || null;

// secundair: varianten waarop dezelfde URL ook rankt.
// Dedupe sorteert al op volume, dus de eerste 3 zijn die met het hoogste volume.
const secondary = (Array.isArray($json.secondary_keywords) ? $json.secondary_keywords : [])
  .map(k => String(k || '').trim())
  .filter(Boolean)
  .filter(k => k.toLowerCase() !== String(primary || '').toLowerCase())
  .slice(0, 3);

return {
  slug,
  primary_keyword: primary,
  secondary_keywords: secondary,
  // alias zodat bestaande expressies op .keyword blijven werken
  keyword: primary
};

