const raw = $json.output;
let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = { picks: [] };
}

const picks = Array.isArray(parsed.picks) ? parsed.picks.slice(0, 5) : [];
const prep = $('Kansen voorbereiden').first().json;
const country = prep.country || 'NL';
const domein = $('On form submission1').first().json.Domeinnaam || '';

// Resume-URL van de Wait-node: klikken op deze links hervat de executie.
// LET OP: de resumeUrl bevat al een querystring (?signature=...), dus de
// approve-parameter moet met & erachter. Een tweede ? maakt de signature
// ongeldig en levert 'Invalid token' op.
let resumeUrl = '';
try { resumeUrl = $execution.resumeUrl || ''; } catch (e) {}
const sep = resumeUrl.includes('?') ? '&' : '?';
const approveUrl = resumeUrl + sep + 'approve=true';
const declineUrl = resumeUrl + sep + 'approve=false';

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const nf = (v) => (v === null || v === undefined || v === '') ? '-' : String(v);

const rows = picks.map((p, i) => {
  const url = esc(p.url);
  return '<tr>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;">' + (i + 1) + '</td>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;"><a href="' + url + '">' + url + '</a></td>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;"><strong>' + esc(p.primary_keyword) + '</strong></td>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;text-align:right;">' + nf(p.volume) + '</td>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;text-align:right;">' + nf(p.position) + '</td>'
    + '<td style="padding:8px 10px;border-bottom:1px solid #e5e5e5;">' + esc(p.country || country) + '</td>'
    + '</tr>';
}).join('');

const btn = (href, label, bg, fg) => '<a href="' + esc(href) + '" style="display:inline-block;padding:12px 22px;'
  + 'margin:0 10px 0 0;border-radius:4px;background:' + bg + ';color:' + fg + ';'
  + 'font-family:Arial,sans-serif;font-size:14px;font-weight:bold;text-decoration:none;">' + label + '</a>';

const html = ''
  + '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;">'
  + '<p>Voor <strong>' + esc(domein) + '</strong> zijn dit de 5 grootste SEO-kansen uit de laatste analyse '
  + '(' + prep.total + ' live kandidaten beoordeeld'
  + (prep.dropped ? ', ' + prep.dropped + ' afgevallen omdat de URL geen 200 gaf' : '')
  + ', zoeknetwerk ' + esc(country) + ').</p>'
  + '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;">'
  + '<tr style="background:#f4f4f4;">'
  + '<th style="padding:8px 10px;text-align:left;">#</th>'
  + '<th style="padding:8px 10px;text-align:left;">Pagina</th>'
  + '<th style="padding:8px 10px;text-align:left;">Hoofdzoekwoord</th>'
  + '<th style="padding:8px 10px;text-align:right;">Zoekvolume</th>'
  + '<th style="padding:8px 10px;text-align:right;">Positie</th>'
  + '<th style="padding:8px 10px;text-align:left;">Land</th>'
  + '</tr>'
  + rows
  + '</table>'
  + '<p style="margin-top:26px;">'
  + btn(approveUrl, 'Goedkeuren en optimaliseren', '#1f7a3d', '#ffffff')
  + btn(declineUrl, 'Afwijzen', '#eeeeee', '#333333')
  + '</p>'
  + '<p style="font-size:13px;color:#555;">Na goedkeuring worden alleen deze pagina&#39;s herschreven en als concept in Craft gezet. '
  + 'Bij afwijzen stopt de flow. Deze links werken 7 dagen en kunnen maar &#233;&#233;n keer gebruikt worden.</p>'
  + '</div>';

return [{ json: { picks, country, domein, total: prep.total, dropped: prep.dropped, approveUrl, declineUrl, html } }];

// Alleen de goedgekeurde pagina's gaan door naar de content-optimalisatie.
// Match op slug in plaats van op de volledige URL: protocol, www. en trailing
// slash zijn er dan al af, dus een genormaliseerde URL van het model matcht ook.
const picks = $('Goedkeuringsmail opmaken').first().json.picks || [];
const all = $('Filter: alleen live URLs').all();

const toSlug = (u) => String(u || '')
  .trim()
  .toLowerCase()
  .replace(/^https?:\/\/[^\/]+\/?/, '')
  .replace(/\/$/, '');

const bySlug = new Map();
all.forEach((item, i) => {
  const key = toSlug(item.json.url_clean || item.json.url);
  if (!bySlug.has(key)) bySlug.set(key, i);
});

const chosen = new Set();
const missing = [];

for (const p of picks) {
  const i = bySlug.get(toSlug(p.url));
  if (i !== undefined) chosen.add(i);
  else missing.push(p.url);
}

// Faal hard in plaats van stil 0 items doorgeven: dan zie je een rode executie
// in plaats van een groene die niets heeft gedaan.
if (picks.length && chosen.size === 0) {
  throw new Error(
    'Geen enkele goedgekeurde pagina teruggevonden. Goedgekeurd: ' +
    JSON.stringify(picks.map(p => p.url))
  );
}

if (missing.length) {
  console.warn('Overgeslagen, slug niet teruggevonden: ' + JSON.stringify(missing));
}

return [...chosen].sort((a, b) => a - b).map(i => all[i]);

