// Pak form input (1x, geldt voor alle items)
const form = $items('On form submission1')[0]?.json ?? {};
const company = form.Bedrijfsnaam || form.Domeinnaam || '';

// Normaliseer tekst
function norm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const clean = norm(company);
const parts = clean.split(' ').filter(Boolean);

const legalSuffixes = new Set([
  'bv','b','b.v','b.v.','nv','n.v','n.v.',
  'holding','group','groep','company','co','co.',
  'bussum','eindhoven'
]);

const filteredParts = parts.filter(p => !legalSuffixes.has(p));

// Brand-varianten bouwen
const brands = new Set();
const add = (v) => { if (v && v.trim()) brands.add(v.trim()); };

const first = filteredParts[0] || '';
const first2 = filteredParts.slice(0, 2).join(' ');
const first3 = filteredParts.slice(0, 3).join(' ');
const noSuffix = filteredParts.join(' ');

add(first);
add(first2);
add(first3);
add(noSuffix);
add(clean);

for (const b of [...brands]) {
  add(b.replace(/\s+/g, ''));
  add(b.replace(/\s+/g, '-'));
}

const brandVariants = [...brands].filter(Boolean);

// Helper: intents altijd als array krijgen
function intentsToArray(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') {
    return v.split(/[,\s]+/).map(s => s.trim()).filter(Boolean);
  }
  return [];
}

// ✅ Belangrijk: ALLE items teruggeven
return items.map(item => {
  const j = item.json;

  const keyword = String(j.keyword || '').toLowerCase();
  const intentsArr = intentsToArray(j.intents);
  const blockType = j.block_type;

  const isBrand = brandVariants.some(b => b && keyword.includes(b));
  const keep =
    !isBrand &&
    (intentsArr.includes('I') || intentsArr.includes('C')) &&
    (blockType === null || blockType === undefined || blockType === '');

  return {
    json: {
      ...j,

      // bedrijf / brand info
      company_name: company,
      company_name_clean: clean,
      brand_variants: brandVariants,

      // intents: array behouden + tekst variant voor Data Table
      intents: intentsArr,
      intents_text: intentsArr.join(','),

      // serp_features (optioneel) ook veilig maken
      serp_features_text: Array.isArray(j.serp_features) ? j.serp_features.join(',') : (j.serp_features ?? ''),

      // jouw filter-flag
      keep,
    }
  };
});

const rows = $input.all();

// Land van zoeknetwerk komt uit de source-parameter van de SE Ranking-node
let country = 'nl';
try {
  country = $('Domain keywords ophalen').params?.source || 'nl';
} catch (e) {}

// Hoeveel kandidaten er vóór de live-check waren, zodat de mail kan melden
// hoeveel er zijn afgevallen omdat de URL geen 200 gaf.
let checked = rows.length;
try {
  checked = $('Cannibalization filter').all().length;
} catch (e) {}

const candidates = rows.map((item, i) => {
  const j = item.json;
  return {
    index: i,
    url: j.url_clean || j.url,
    primary_keyword: j.primary_keyword || j.keyword_clean || j.keyword,
    volume: Number(j.volume ?? 0),
    position: Number(j.position ?? 0),
    difficulty: Number(j.difficulty ?? 0),
    intents: Array.isArray(j.intents) ? j.intents.join(',') : (j.intents ?? ''),
    secondary_keywords: Array.isArray(j.secondary_keywords) ? j.secondary_keywords : [],
  };
});

return [{
  json: {
    country: String(country).toUpperCase(),
    total: candidates.length,
    checked,
    dropped: Math.max(0, checked - candidates.length),
    candidates,
  }
}];

