// Pairt de HTTP-responses terug op de kandidaten en houdt alleen live pagina's over.
// De HTTP Request-node levert exact 1 output-item per input-item, dus index-pairing is veilig.
const responses = $input.all();
const source = $('Cannibalization filter').all();

const out = [];
const dropped = [];

for (let i = 0; i < responses.length; i++) {
  const r = responses[i].json || {};
  const src = source[i] ? source[i].json : {};
  const url = src.url_clean || src.url || '';

  // neverError levert statusCode; een netwerkfout levert een error-object
  const status = Number(
    r.statusCode ?? (r.error && (r.error.status ?? r.error.httpCode)) ?? 0
  );

  const headers = r.headers || {};
  const location = headers.location || headers.Location || '';

  if (status === 200) {
    out.push({ json: { ...src, http_status: status } });
  } else {
    dropped.push({ url, status: status || 'geen respons', location });
  }
}

if (dropped.length) {
  console.warn('Niet live, uit de kansen gehaald: ' + JSON.stringify(dropped));
}

if (out.length === 0) {
  throw new Error(
    'Geen enkele kandidaat-URL geeft een 200 terug (' + responses.length + ' gecontroleerd). ' +
    'Controleer of het domein bereikbaar is voordat je dit opnieuw start.'
  );
}

return out;
